/// <summary>
/// init curExt()
/// </summary>
/// <param name="sender">CredManCreditLimitCustGroup</param>
/// <param name="e">DataEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    DataEventHandler(tableStr(CredManCreditLimitCustGroup), DataEventType::InitializedRecord)]
public static void CredManCreditLimitCustGroup_onInitializedRecord(Common sender, DataEventArgs e)
{
    CredManCreditLimitCustGroup     crlCustGroup = sender;
    crlCustGroup.AVACompanyId = curExt();
}

/// <summary>
/// add line with AVARiscDebtor
/// </summary>
/// <param name="sender">CredManCreditLimitCustGroup</param>
/// <param name="e">DataEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    DataEventHandler(tableStr(CredManCreditLimitCustGroup), DataEventType::Inserted)]
public static void CredManCreditLimitCustGroup_onInserted(Common sender, DataEventArgs e)
{
    CredManCreditLimitCustGroupLine     crlCustGroupLine;
    CredManCreditLimitCustGroup         crlCustGroup = sender;

    crlCustGroupLine.CreditLimitCustGroup   = crlCustGroup.RecId;
    crlCustGroupLine.Company                = crlCustGroup.AVACompanyId;
    crlCustGroupLine.CustAccount            = crlCustGroup.AVARiscDebtor;
    crlCustGroupLine.insert();
}
